{"command":"cat > /work/prices.py <<'PY'
import json
import os
import urllib.parse
import urllib.request

BASE = os.environ.get(
    "PRICING_BASE_URL", "http://pricing-v2.internal:8081/api/v2/price"
)


def get_price(sku: str) -> float:
    url = f"{BASE.rstrip('/')}/{urllib.parse.quote(sku, safe='')}"
    headers = {}
    if key := os.environ.get("PRICING_API_KEY"):
        headers["X-Pricing-Key"] = key

    request = urllib.request.Request(url, headers=headers)
    with urllib.request.urlopen(request, timeout=5) as response:
        return float(json.load(response)["price"])


def get_total(skus: list) -> float:
    return sum(map(get_price, skus))
PY
